128	    ```typescript
129	      ariaLabel(rowLabel: string, cell: SeatMapCell): string {
130	        const statusText = cell.status === 'occupied'
131	          ? 'belegt'
132	          : this.isSelected(rowLabel, cell.columnNumber) ? 'ausgewählt' : 'frei';
133	        return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
