142	        [class.seat-cell--free]="!isSelected(row.rowLabel, cell.columnNumber)"
143	        [class.seat-cell--selected]="isSelected(row.rowLabel, cell.columnNumber)"
144	        role="gridcell"
145	        [attr.aria-label]="ariaLabel(row.rowLabel, cell)"
146	        [attr.tabindex]="isRovingTabTarget(rowIndex, columnIndex) ? 0 : -1"
147	        [attr.data-row-index]="rowIndex"
148	        [attr.data-column-index]="columnIndex"
149	        (click)="onToggle(row.rowLabel, cell.columnNumber)"
150	        (focus)="onFocus(rowIndex, columnIndex)"
151	        (keydown)="onKeydown($event, rowIndex, columnIndex)"
152	      >
153	        <span
154	          class="seat-cell__icon"
155	          [class.seat-cell__icon--seat]="!isSelected(row.rowLabel, cell.columnNumber)"
156	          [class.seat-cell__icon--check]="isSelected(row.rowLabel, cell.columnNumber)"
157	          aria-hidden="true"
