93	  private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
94	    const rows = this.seatMap().rows;
95	    let r = rowIndex + rowDelta;
96	    let c = columnIndex + columnDelta;
97	    while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
98	      if (rows[r].cells[c].status === 'free') {
99	        return { rowIndex: r, columnIndex: c };
100	      }
101	      r += rowDelta;
102	      c += columnDelta;
103	    }
104	    return null;
