38	    @Injectable()
39	    export class BookingSelectionService {
40	      private readonly selectedSeatsState = signal<SelectedSeat[]>([]);
41	
42	      readonly selectedSeats = this.selectedSeatsState.asReadonly();
43	
44	      isSelected(rowLabel: string, columnNumber: number): boolean {
45	        return this.selectedSeatsState().some(seat => seat.rowLabel === rowLabel && seat.columnNumber === columnNumber);
46	      }
47	
