1	import { Component, ElementRef, computed, effect, inject, input, signal, viewChild } from '@angular/core';
2	
3	import { SeatMap, SeatMapCell } from '../../../core/api/seat-map';
4	import { BookingSelectionService } from '../booking-selection.service';
5	
6	interface FocusTarget {
7	  rowIndex: number;
8	  columnIndex: number;
9	}
10	
11	const KEY_DELTAS: Record<string, { rowDelta: number; columnDelta: number }> = {
12	  ArrowUp: { rowDelta: -1, columnDelta: 0 },
13	  ArrowDown: { rowDelta: 1, columnDelta: 0 },
14	  ArrowLeft: { rowDelta: 0, columnDelta: -1 },
15	  ArrowRight: { rowDelta: 0, columnDelta: 1 }
16	};
17	
18	@Component({
19	  selector: 'app-seat-map',
20	  imports: [],
21	  templateUrl: './seat-map.html',
22	  styleUrl: './seat-map.scss'
23	})
24	export class SeatMapGrid {
25	  readonly seatMap = input.required<SeatMap>();
26	
27	  private readonly selection = inject(BookingSelectionService);
28	
29	  private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');
30	
31	  private readonly focusTarget = signal<FocusTarget | null>(null);
32	
33	  private readonly firstFreeTarget = computed<FocusTarget | null>(() => {
34	    const rows = this.seatMap().rows;
35	    for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
36	      const columnIndex = rows[rowIndex].cells.findIndex(cell => cell.status === 'free');
37	      if (columnIndex !== -1) {
38	        return { rowIndex, columnIndex };
39	      }
40	    }
41	    return null;
42	  });
43	
44	  readonly hasFreeSeats = computed(() => this.firstFreeTarget() !== null);
45	
46	  constructor() {
47	    effect(() => {
48	      const target = this.focusTarget();
49	      if (target === null) {
50	        return;
51	      }
52	      const selector = `[data-row-index="${target.rowIndex}"][data-column-index="${target.columnIndex}"]`;
53	      this.root().nativeElement.querySelector<HTMLButtonElement>(selector)?.focus();
54	    });
55	  }
56	
57	  isRovingTabTarget(rowIndex: number, columnIndex: number): boolean {
58	    const current = this.focusTarget() ?? this.firstFreeTarget();
59	    return current !== null && current.rowIndex === rowIndex && current.columnIndex === columnIndex;
60	  }
61	
62	  ariaLabel(rowLabel: string, cell: SeatMapCell): string {
63	    const statusText = cell.status === 'occupied'
64	      ? 'belegt'
65	      : this.isSelected(rowLabel, cell.columnNumber) ? 'ausgewählt' : 'frei';
66	    return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
67	  }
68	
69	  isSelected(rowLabel: string, columnNumber: number): boolean {
70	    return this.selection.isSelected(rowLabel, columnNumber);
71	  }
72	
73	  onToggle(rowLabel: string, columnNumber: number): void {
74	    this.selection.toggle(rowLabel, columnNumber);
75	  }
76	
77	  onFocus(rowIndex: number, columnIndex: number): void {
78	    this.focusTarget.set({ rowIndex, columnIndex });
79	  }
80	
81	  onKeydown(event: KeyboardEvent, rowIndex: number, columnIndex: number): void {
82	    const delta = KEY_DELTAS[event.key];
83	    if (!delta) {
84	      return;
85	    }
86	    event.preventDefault();
87	    const next = this.findNextFocusable(rowIndex, columnIndex, delta.rowDelta, delta.columnDelta);
88	    if (next) {
89	      this.focusTarget.set(next);
90	    }
91	  }
92	
93	  private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
94	    const rows = this.seatMap().rows;
95	    let r = rowIndex + rowDelta;
96	    let c = columnIndex + columnDelta;
97	    while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
98	      if (rows[r].cells[c].status === 'free') {
99	        return { rowIndex: r, columnIndex: c };
100	      }
101	      r += rowDelta;
102	      c += columnDelta;
103	    }
104	    return null;
105	  }
106	}
